/* 3.8.48: restore the 3.8.22 canvas theme state exactly after the 3.8.46 migration. */
(()=>{
  const defaults={boardLight:"#f7f8fb",boardDark:"#171a20",gridColorLight:"#c8ceda",gridColorDark:"#4a5262"};
  let changed=false;
  (state.projects||[]).forEach(p=>{const c=p?.canvas;if(!c||!c._themeOrder46)return;Object.assign(c,defaults);delete c._themeOrder46;changed=true});
  document.documentElement.dataset.theme=state.theme;
  applyCanvasStyle();renderObjects();
  if(changed)queuePersist();
})();

